// Deterministic churn risk score. The LLM explains this score; it never sets it.
const b = $json.body ?? $json;
const num = (v, d = 0) => { const n = Number(v); return Number.isFinite(n) ? n : d; };

const overdue = num(b.overdue_tasks);
const daysSinceContact = num(b.days_since_last_contact);
const openTickets = num(b.open_support_tickets);
const trend = num(b.engagement_trend_pct);
const hasNps = b.nps_score !== undefined && b.nps_score !== null && b.nps_score !== '';
const nps = hasNps ? num(b.nps_score, null) : null;

let risk = 0;
const signals = [];

if (overdue > 0) {
  const p = Math.min(overdue * 8, 30);
  risk += p; signals.push(`${overdue} overdue task(s) (+${p})`);
}
if (daysSinceContact > 30) {
  risk += 20; signals.push(`No contact in ${daysSinceContact} days (+20)`);
} else if (daysSinceContact > 14) {
  risk += 10; signals.push(`No contact in ${daysSinceContact} days (+10)`);
}
if (openTickets > 0) {
  const p = Math.min(openTickets * 5, 20);
  risk += p; signals.push(`${openTickets} open support ticket(s) (+${p})`);
}
if (trend < 0) {
  const p = Math.round(Math.min(Math.abs(trend) * 0.5, 25));
  risk += p; signals.push(`Engagement down ${Math.abs(trend)}% vs last period (+${p})`);
}
if (nps !== null) {
  if (nps <= 6) { risk += 15; signals.push(`NPS ${nps} (detractor) (+15)`); }
  else if (nps <= 8) { risk += 5; signals.push(`NPS ${nps} (passive) (+5)`); }
}

let daysToRenewal = null;
if (b.renewal_date) {
  const d = new Date(b.renewal_date);
  if (!isNaN(d)) daysToRenewal = Math.ceil((d - new Date()) / 86400000);
}
if (daysToRenewal !== null && daysToRenewal >= 0 && daysToRenewal <= 60 && risk >= 30) {
  risk += 10; signals.push(`Renewal in ${daysToRenewal} days while at risk (+10)`);
}

risk = Math.min(risk, 100);
const level = risk >= 70 ? 'critical' : risk >= 50 ? 'high' : risk >= 30 ? 'medium' : 'low';

return {
  json: {
    client_id: String(b.client_id),
    client_name: b.client_name,
    account_owner_email: b.account_owner_email || null,
    renewal_date: b.renewal_date || null,
    days_to_renewal: daysToRenewal,
    risk_score: risk,
    risk_level: level,
    risk_signals: signals,
    input: b,
  },
};

