// Combine the score with the AI output into one flat record for Airtable.
const s = $('Compute Health Score').item.json;
const ai = $json.output;
const bullets = (arr) => (Array.isArray(arr) && arr.length ? arr.map((a) => `- ${a}`).join('\n') : '- None');

return {
  json: {
    assessed_at: new Date().toISOString(),
    client_id: s.client_id,
    client_name: s.client_name,
    account_owner_email: s.account_owner_email,
    risk_score: s.risk_score,
    risk_level: s.risk_level,
    days_to_renewal: s.days_to_renewal,
    risk_signals: bullets(s.risk_signals),
    summary: ai.summary,
    primary_risk_driver: ai.primary_risk_driver,
    actions_immediate: bullets(ai.actions_immediate),
    actions_short_term: bullets(ai.actions_short_term),
    actions_long_term: bullets(ai.actions_long_term),
  },
};
